          className
        )}
      >
        <div className='flex items-start gap-3 p-4'>
          <Icon className={cn('mt-0.5 h-5 w-5 flex-shrink-0', config.iconColor)} />
          <p className={cn('flex-1 text-sm font-medium leading-6', config.textColor)}>{message}</p>
